def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp_last = history[-1][1]
    my_last = history[-1][0]
    prev_my = history[-2][0]

    recent = history[-10:] if n >= 10 else history
    opp_def_recent = sum(1 for a, b in recent if b == 'D')
    total_opp_def = sum(1 for a, b in history if b == 'D')
    total_my_def = sum(1 for a, b in history if a == 'D')

    unprov = 0
    prev_m = 'C'
    for i in range(n):
        m, o = history[i]
        if o == 'D' and prev_m == 'C':
            unprov += 1
        prev_m = m

    streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak += 1
        else:
            break

    if total_opp_def == 0:
        return 'C'
    if n >= 2 and total_opp_def == n:
        return 'D'

    if opp_last == 'D':
        if my_last == 'C' and prev_my == 'D' and streak <= 1 and unprov <= 1:
            return 'C'
        if my_last == 'D' and streak <= 1 and unprov <= 1:
            return 'C'
        if streak >= 2 or opp_def_recent >= 7:
            return 'D'

        opp_rate = total_opp_def / n
        my_rate = total_my_def / n

        if opp_rate <= 0.15 and my_rate <= 0.2 and unprov <= 1:
            return 'C'
        if opp_rate <= 0.35:
            if unprov >= 2:
                return 'D'
            return 'D' if rng.random() < 0.5 else 'C'
        if opp_rate < 0.6:
            return 'D'
        if unprov <= 1 and my_rate > 0.5:
            return 'C'
        return 'D' if rng.random() < 0.85 else 'C'

    if my_last == 'D':
        if total_opp_def == 0 and total_my_def >= 3 and n >= 20:
            return 'D'
        return 'C'
    return 'C'
